const staticData = $getWorkflowStaticData('global');
const session = $node['Normalize + Validate Input'].json;
const discovered = $node['Wikidata Search Entities'].json;
const runId = session.runId;
const run = staticData.runs?.[runId];

const seedUrls = discovered.seedUrls || [];
const discoveryMethod = discovered.discoveryMethod || 'hardcoded';

// Try to extract additional URLs from DuckDuckGo if available
const ddgRaw = $input.first().json;
const found = [];
if (ddgRaw?.data || typeof ddgRaw === 'string') {
  const html = ddgRaw?.data || (typeof ddgRaw === 'string' ? ddgRaw : '');
  const re = /uddg=([^&"]+)/g;
  let m;
  while ((m = re.exec(html)) !== null) {
    try {
      const url = decodeURIComponent(m[1]);
      if (url.startsWith('http')) found.push(url);
    } catch(e) {}
  }
}

function scoreUrl(u) {
  let s = 0;
  const lu = u.toLowerCase();
  if (lu.includes('gob.ar') || lu.includes('gov.ar')) s += 5;
  if (lu.includes('municip') || lu.includes('comuna')) s += 2;
  if (lu.includes('transpar')) s += 3;
  if (lu.endsWith('.pdf')) s += 4;
  if (lu.endsWith('.csv') || lu.endsWith('.xlsx')) s += 4;
  if (lu.includes('/api/') || lu.includes('ckan') || lu.includes('datastore')) s += 5;
  if (lu.includes('boletin')) s += 4;
  if (lu.includes('ordenanza') || lu.includes('decreto') || lu.includes('resolucion')) s += 4;
  if (lu.includes('licit') || lu.includes('compra') || lu.includes('contrat')) s += 3;
  if (lu.includes('presup') || lu.includes('ejecuc')) s += 3;
  if (lu.includes('auditor')) s += 3;
  if (lu.includes('facebook') || lu.includes('twitter') || lu.includes('instagram')) s -= 10;
  if (lu.includes('whatsapp') || lu.includes('youtube')) s -= 10;
  return s;
}

// Combine seedURLs + DDG results, deduplicate, score and sort
const all = [...seedUrls, ...found];
const uniq = [...new Set(all)].filter(u => {
  if (typeof u !== 'string') return false;
  if (!u.startsWith('http')) return false;
  const lu = u.toLowerCase();
  if (lu.includes('facebook') || lu.includes('twitter') || lu.includes('instagram')) return false;
  if (lu.includes('whatsapp') || lu.includes('youtube') || lu.includes('tiktok')) return false;
  return true;
});
uniq.sort((a, b) => scoreUrl(b) - scoreUrl(a));

// CRITICAL: Separate PDFs from HTML pages.
// PDFs cannot be processed by the 1st-pass OCR.Space node (disabled).
// Route them to run._harvested so Build 2nd Pass Queue stores them
// directly in run.docs for Claude URL-based extraction.
const isPdf = u => {
  const lu = u.toLowerCase();
  return lu.endsWith('.pdf') || lu.endsWith('.csv') || lu.endsWith('.xlsx');
};
const pdfSeeds = uniq.filter(isPdf);
const htmlSeeds = uniq.filter(u => !isPdf(u));

if (run && pdfSeeds.length > 0) {
  run._harvested = run._harvested || [];
  for (const u of pdfSeeds) {
    if (!run._harvested.includes(u)) run._harvested.push(u);
  }
  run.logs.push({ t: new Date().toISOString(), m: `Pre-seeded ${pdfSeeds.length} PDFs into 2nd-pass queue (bypassing disabled OCR)` });
}

const maxUrls = session.isPremium ? 40 : 15;
const queue = htmlSeeds.slice(0, maxUrls);

if (run) {
  run.step = 'discover_sources';
  run.progress = 18;
  run.discoveryMethod = discoveryMethod;
  run.logs.push({
    t: new Date().toISOString(),
    m: `1st-pass: ${queue.length} HTML pages | 2nd-pass: ${pdfSeeds.length} PDFs pre-seeded [method: ${discoveryMethod}]`
  });
}

if (queue.length === 0 && pdfSeeds.length === 0) {
  if (run) {
    run.logs.push({ t: new Date().toISOString(), m: 'WARNING: Empty URL queue' });
    run.status = 'error';
    run.error = 'No se encontraron fuentes publicas para este municipio';
  }
  return [];
}

// If no HTML to fetch in 1st pass, return a dummy item so Split URLs
// runs and triggers Build 2nd Pass Queue via its done output.
if (queue.length === 0) {
  return [{ json: { runId, localityName: session.localityName, dateFrom: session.dateFrom, dateTo: session.dateTo, isPremium: session.isPremium, discoveryMethod, url: 'https://altagracia.gob.ar', _skipFirstPass: true } }];
}

return queue.map(url => ({
  runId,
  localityName: session.localityName,
  dateFrom: session.dateFrom,
  dateTo: session.dateTo,
  isPremium: session.isPremium,
  discoveryMethod,
  url
}));
